// Pilot avatars: portraits (AI art, generated by tools/pilots/export_ai.py into pilots_data.ts), bios, choice persistence and drawing.
import { PILOT_IMAGES } from "./pilots_data";

export const PILOT_BIOS: Record<string, string[]> = {
  "KAGE": ["MASKED SHINOBI ACE.", "NEVER SEEN.", "NEVER MISSED."],
  "VOSS": ["FORTY-WAR MERC.", "CHEWS A CIGAR HE", "NEVER LIGHTS."],
  "SABLE": ["EXILED WARRIOR", "QUEEN. FLIES TO BUY", "BACK HER THRONE."],
  "IRONCLAD": ["NOBODY KNOWS WHO IS", "IN THE ARMOUR.", "OR IF ANYONE IS."],
  "HEX": ["CYBORG HACKER.", "FLIES BY JACKING", "INTO THE SHIP."],
  "ZORUK": ["REPTILE WARLORD.", "COLLECTS THE FINS", "OF DOWNED SHIPS."],
  "WRAITH": ["ALIEN SEER. READS", "THE BATTLE BEFORE", "IT BEGINS."],
  "FANG": ["WOLF OF THE", "ICE MOONS. HUNTS", "IN SILENCE."],
  "MARISOL": ["SMUGGLER. PRICE ON", "HER HEAD, SMIRK", "TO MATCH."],
  "BRICK": ["HEAVY GUNNER.", "CARRIES THE SQUAD.", "NEVER COMPLAINS."],
  "TALON": ["OLD-SCHOOL JOCK.", "FLIES WITH THE", "VISOR UP."],
  "VESPER": ["VETERAN SNIPER.", "ONE EYE.", "ONE SHOT."],
  "JINX": ["STREET RACER.", "NEVER LOST A HEAT.", "BORED OF WINNING."],
  "CINDER": ["PYRO ACE. WALKED", "OUT OF A REACTOR", "FIRE. STILL BURNS."],
  "VULCAN": ["MAGMA-BLOODED BRUTE", "FROM A DYING SUN.", "MELTS WHAT HE HITS."],
};
export const PILOT_NAMES = PILOT_IMAGES.map(p => p.name);
export const PILOT_COUNT = PILOT_NAMES.length;
/** Stored choice: 0..PILOT_COUNT-1, or RANDOM_PILOT (a new pick every match). */
export const RANDOM_PILOT = -1;
const LS = "sf101pilot2"; // v2 roster (13 new pilots): old "sf101pilot" choices referred to the retired 7, so start fresh

type Size = 136 | 48 | 40;
const imgs: Record<Size, HTMLImageElement>[] = typeof Image === "undefined" ? [] : PILOT_IMAGES.map(p => {
  const mk = (b: string) => { const i = new Image(); i.src = "data:image/jpeg;base64," + b; return i; };
  return { 136: mk(p.s136), 48: mk(p.s48), 40: mk(p.s40) };
});

export function loadPilotChoice(): number {
  try { const v = localStorage.getItem(LS); if (v === null) return 0; const n = Math.floor(Number(v)); return n === RANDOM_PILOT || (n >= 0 && n < PILOT_COUNT) ? n : 0; } catch { return 0; }
}
export function savePilotChoice(v: number) { try { localStorage.setItem(LS, String(v)); } catch { /* private mode */ } }
/** The pilot actually flown this match (resolves RANDOM). */
export function resolvePilot(choice: number) { return choice >= 0 && choice < PILOT_COUNT ? choice : Math.floor(Math.random() * PILOT_COUNT); }
/** Bots and players without a choice get a stable pilot from their callsign. */
export function pilotForName(name: string) { let h = 2166136261; for (let i = 0; i < name.length; i++) { h ^= name.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0) % PILOT_COUNT; }
export function validPilot(v: unknown): number | undefined { const n = Number(v); return Number.isInteger(n) && n >= 0 && n < PILOT_COUNT ? n : undefined; }

/** Draw a portrait at its native size with a 1px frame (and a dark keyline outside it). mirror = face right. */
export function drawPilot(ctx: CanvasRenderingContext2D, idx: number, size: Size, x: number, y: number, frame?: string, mirror = false) {
  const im = imgs[idx]?.[size];
  if (frame) { ctx.fillStyle = "#05040c"; ctx.fillRect(x - 2, y - 2, size + 4, size + 4); ctx.fillStyle = frame; ctx.fillRect(x - 1, y - 1, size + 2, size + 2); }
  if (!im || !im.complete) { ctx.fillStyle = "#0c0824"; ctx.fillRect(x, y, size, size); return; }
  const sm = ctx.imageSmoothingEnabled; ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high"; // painted portraits: smooth
  if (mirror) { ctx.save(); ctx.translate(x + size, y); ctx.scale(-1, 1); ctx.drawImage(im, 0, 0, size, size); ctx.restore(); }
  else ctx.drawImage(im, x, y, size, size);
  ctx.imageSmoothingEnabled = sm;
}
